BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(20);
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_allocations'::regclass AND conname='db03_handoff_number_source_key' AND contype='u' AND cardinality(conkey)=4),'number ledger has composite application Kind State reference key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_number_same_application' AND contype='f' AND cardinality(conkey)=4),'handoff has four-field permanent number FK');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_number_same_application' AND conrelid='app_private.admission_student_handoffs'::regclass AND confrelid='app_private.admission_number_allocations'::regclass),'handoff FK refers to the Admission ledger, not a client declaration');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_number_same_application' AND pg_get_constraintdef(oid) LIKE '%admission_number_allocation_id, application_id, admission_number_kind, admission_number_state%'),'FK binds number ID, application, kind and state together');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_number_same_application' AND confupdtype='r' AND confdeltype='r'),'linked permanent number cannot be reassigned or deleted');
SELECT ok((SELECT count(*)=1 FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='admission_number_allocation_id' AND attnotnull AND NOT attisdropped),'handoff must record a permanent number allocation');
SELECT ok((SELECT count(*)=1 FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='admission_number_kind' AND attnotnull AND NOT attisdropped),'handoff number Kind is non-null');
SELECT ok((SELECT count(*)=1 FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='admission_number_state' AND attnotnull AND NOT attisdropped),'handoff number State is non-null');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_number_kind_exact' AND contype='c' AND pg_get_constraintdef(oid) LIKE '%ADMISSION%'),'cannot use an APPLICATION number as permanent Admission number');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_number_state_exact' AND contype='c' AND pg_get_constraintdef(oid) LIKE '%ALLOCATED%'),'cannot use a canceled number allocation');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_number_one_link' AND contype='u'),'a permanent allocation binds to no more than one handoff');
SELECT ok((SELECT count(*)=2 FROM pg_class WHERE oid IN('app_private.admission_student_handoffs'::regclass,'app_private.admission_number_allocations'::regclass) AND relrowsecurity AND relforcerowsecurity),'both private ledgers still force RLS');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_student_handoffs','INSERT') AND NOT has_table_privilege('service_role','app_private.admission_student_handoffs','INSERT') AND NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_number_allocations','INSERT'),'no new client, service or executor writer grant');
SELECT ok((SELECT count(*)=2 FROM pg_trigger WHERE tgname IN('db03_handoff_mutation_disabled','db03_number_allocations_mutation_disabled') AND NOT tgisinternal AND tgenabled='O'),'handoff and number writers remain denied');
SELECT ok((SELECT count(*)=2 FROM pg_trigger WHERE tgname IN('db03_handoff_no_truncate','db03_number_allocations_no_truncate') AND NOT tgisinternal AND tgenabled='O'),'both immutable histories still deny truncate');
SELECT ok((SELECT count(*)=3 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname IN('db03_handoff_identity_same_application','db03_handoff_fee_same_application','db03_handoff_grade_same_application')),'identity, fee and Grade origin links preserved');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_student_handoffs'::regclass AND conname='db03_handoff_section_same_class'),'Section and Grade FK preserved');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_number_allocations'::regclass AND conname='db03_number_application_kind_unique'),'allocation remains unique per application and Kind');
SELECT throws_ok($q$INSERT INTO app_private.admission_student_handoffs DEFAULT VALUES$q$,'P0001','DB03 atomic Student handoff writer unavailable','no usable handoff issuer created');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL AND to_regprocedure('app.allocate_admission_number(uuid,uuid)') IS NULL,'Principal APPROVE and number issuer remain unavailable');
SELECT * FROM finish();
ROLLBACK;
